<script setup lang="ts">
import {ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useAuth} from '../stores/auth'
import {dataMode} from '../services'
import {errorText} from '../composables/useData'
import Brand from '../components/Brand.vue'
import DotField from '../components/DotField.vue'
import Icon from '../components/Icon.vue'
const auth=useAuth(),router=useRouter(),route=useRoute(),username=ref(''),password=ref(''),busy=ref(false),error=ref(''),showPassword=ref(false),alternate=ref(false)
const accounts=[{name:'系统管理员',username:'admin'},{name:'知识管理员',username:'knowledge'},{name:'普通用户',username:'member'}]
function choose(account:string){username.value=account;password.value='Demo@123';error.value=''}
async function submit(){if(!username.value.trim()||!password.value){error.value='请输入用户名和密码';return}busy.value=true;error.value='';try{await auth.login(username.value.trim(),password.value);const target=String(route.query.redirect||'');await router.replace(target.startsWith('/')&&!target.startsWith('//')&&!['/login','/403'].includes(target)?target:auth.home)}catch(e){error.value=errorText(e)}finally{busy.value=false}}
</script>
<template><main class="login"><DotField /><section class="login-art"><Brand /><div class="login-story"><button class="pixel-stage" aria-label="切换知识图形" @click="alternate=!alternate"><svg viewBox="0 0 220 220" aria-hidden="true"><g v-if="!alternate" fill="none" stroke="currentColor" stroke-width="6"><path d="M110 177V54L52 34H28V154H52L110 177 168 154H192V34H168L110 54"/><path d="M47 61H60L87 71M47 88H60L87 98M47 115H60L87 125M133 71L160 61H173M133 98L160 88H173M133 125L160 115H173"/></g><g v-else fill="currentColor"><rect x="87" y="87" width="46" height="46"/><rect x="32" y="32" width="27" height="27"/><rect x="161" y="32" width="27" height="27"/><rect x="32" y="161" width="27" height="27"/><rect x="161" y="161" width="27" height="27"/><path d="M54 48L94 88 88 94 48 54zM166 48L126 88 132 94 172 54zM48 166L88 126 94 132 54 172zM172 166L132 126 126 132 166 172z"/></g></svg></button><h1><span>有序归档，</span><span>有据可答。</span></h1><p>把文档沉淀为团队知识，让每一次提问都能找到有权限、有来源的答案。</p><div class="login-tags"><span>权限可控</span><span>引用可溯</span><span>持续沉淀</span></div></div><footer class="login-footer"><span>团队知识 · 安全连接</span><span>暗色 / 轻像素动态</span></footer></section><section class="login-side"><form class="login-form" @submit.prevent="submit"><span class="eyebrow">团队工作空间</span><h2>登录，连接团队知识。</h2><p class="muted">使用你的团队账号，访问被授权的知识。</p><label class="field">用户名<input v-model="username" name="username" autocomplete="username" placeholder="输入用户名" required :disabled="busy"></label><label class="field">密码<span class="password-input"><input v-model="password" name="password" autocomplete="current-password" :type="showPassword?'text':'password'" placeholder="输入密码" required :disabled="busy"><button type="button" @click="showPassword=!showPassword" :aria-label="showPassword?'隐藏密码':'显示密码'">{{showPassword?'隐藏':'显示'}}</button></span></label><p v-if="error" class="field-error" role="alert">{{error}}</p><button class="btn primary submit" :disabled="busy">{{busy?'正在登录…':'进入工作空间'}}<Icon name="arrow" /></button><template v-if="dataMode==='demo'"><div class="demo-accounts"><p>选择演示身份</p><div><button v-for="account in accounts" :key="account.username" type="button" :class="{selected:username===account.username}" @click="choose(account.username)">{{account.name}}</button></div><small>演示密码：Demo@123 · 仅用于本地体验</small></div><p class="form-note">当前为本地演示，账号信息不会发送到服务器。</p></template><p v-else class="form-note">请使用管理员分配的账号。需要帮助时请联系团队系统管理员。</p><div class="form-bottom"><span class="live-dot" />{{dataMode==='demo'?'本地演示空间':'团队知识服务'}}</div></form></section></main></template>
